/** 📖️ Reads the existing production ledger and refuses missing, changed or foreign selected bytes. */
export function readTrustedCatalogPublicationProvenanceV1(dataRoot:string):{path:string;record:TrustedCatalogPublicationProducerV1;generationPath:string;generation:any} {
