  const observationRoot=join(dataRoot,"trusted-catalog","provenance","generations",record.generationId);
  for(const claim of generation.packages.flatMap((row:any)=>[...row.cargoInvocations,...(row.browserActor?[row.browserActor]:[])])){if(typeof claim?.path!=="string"||!inside(observationRoot,claim.path))throw new Error("trusted producer observation claim escaped");matches(claim.path,claim);}
